descriptor.controllerScript:
self.onInit = function () {
  // Tailwind injection
  if (!document.getElementById('tailwindcss')) {
    const script = document.createElement('script');
    script.src = 'https://cdn.tailwindcss.com';
    script.id = 'tailwindcss';
    script.onload = () => self.ctx.detectChanges();
    document.head.appendChild(script);
  }

  // Init state
  self.air = 'N/A';
  self.air_ts = '';
  self.air_raw = 'N/A';
  self.flash = false;

  function formatTime(ts) {
    return new Date(ts).toLocaleTimeString();
  }

  function animateFlash() {
    self.flash = true;
    setTimeout(() => {
      self.flash = false;
      self.ctx.detectChanges();
    }, 500);
  }

  self.onDataUpdated = function () {
    const dp = self.ctx.data.find(d => d.dataKey.name === 'air');
    if (dp && dp.data.length > 0) {
      const [ts, value] = dp.data.at(-1);
      const val = parseFloat(value).toFixed(2);

      if (val !== self.air) animateFlash();
      self.air_raw = value;
      self.air = val;
      self.air_ts = formatTime(ts);
    }

    self.ctx.detectChanges();
  };
};

self.typeParameters = function () {
  return {
    maxDatasources: 1,
    maxDataKeys: 1,
    singleEntity: true,
    previewWidth: '250px',
    previewHeight: '250px',
    embedTitlePanel: true,
    defaultDataKeysFunction: () => [{
      name: 'air',
      label: 'Air Quality Index',
      type: 'timeseries'
    }]
  };
};

self.onDestroy = function () {
  // Clean-up logic if needed
};

